window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[365]={"id":"365","numero":365,"titre":"Surveillance d'un malade sous plâtre","objectifs":[{"id":"365-1","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de réalisation d’une contention plâtrée/résine","contenu":"<p>Une <span class=\"kw-def\">contention plâtrée</span> vise à <strong>maintenir sans danger</strong> une articulation ou un segment de squelette jusqu'à la <span class=\"kw-def\">consolidation</span> des lésions. La mise en place est un geste médical : même réalisée par un auxiliaire, le <strong>médecin en assume la responsabilité</strong>.</p>\n      <h4 class=\"kw-def\">Indication : seule ou après <span class=\"kw-ttt\">chirurgie</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Traitement orthopédique</span> :</strong> immobilisation directe, sans <span class=\"kw-ttt\">réduction</span> ou après réduction d'une <span class=\"kw-etio\">fracture</span> par manœuvre externe, <strong>sans ouvrir le foyer</strong> (idem pour une entorse ou une luxation après réduction)</li>\n        <li><strong><span class=\"kw-bio\">Complément</span> d'une <span class=\"kw-ttt\">chirurgie</span> :</strong> immobilisation plâtrée après <span class=\"kw-ttt\">réduction</span> puis <span class=\"kw-ttt\">ostéosynthèse</span> à foyer ouvert</li>\n      </ul>\n      <h4 class=\"kw-def\">Type, étendue et position</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Circulaire ou gouttière</strong></td>\n            <td><strong>Plâtre circulaire :</strong> entoure tout le membre<br><strong>Gouttière plâtrée postérieure (<span class=\"kw-def\">GPP</span>) :</strong> moitié postérieure du membre, maintenue par une bande qui ne doit pas serrer</td>\n          </tr>\n          <tr>\n            <td><strong>Étendue</strong></td>\n            <td><strong>Immobiliser une fracture :</strong> prendre <span class=\"kw-clinique\">les</span> articulations <span class=\"kw-clinique\">sus- et sous-jacentes</span> (ex. fracture de jambe → plâtre cruro-pédieux genou + cheville)<br><strong>Immobiliser une articulation :</strong> prendre les pièces osseuses sus- et sous-jacentes<br><strong>Toujours laisser libres les doigts et orteils</strong> pour les mobiliser et surveiller sensibilité/motricité</td>\n          </tr>\n          <tr>\n            <td><strong>Position du membre</strong></td>\n            <td>Maintenir en <span class=\"kw-def\">position de fonction</span>, proscrire <span class=\"kw-clinique\">les</span> positions extrêmes :<br><strong>Membre supérieur :</strong> coude à <span class=\"kw-chiffre\">90°</span> de flexion, pro-supination intermédiaire, poignet en extension neutre, pouce en opposition<br><strong>Membre inférieur :</strong> genou à <span class=\"kw-chiffre\">10° de flexion</span>, cheville à <span class=\"kw-chiffre\">90°</span>, lutte contre le varus de l'arrière-pied</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Réalisation</h4>\n      <ul>\n        <li><strong>Avant :</strong> retirer <span class=\"kw-alerte\">bagues et anneaux</span> ; proscrire tout pansement circulaire sous le plâtre ; peau lavée et séchée puis <span class=\"kw-def\">jersey tubulaire</span> sans pli</li>\n        <li><strong>Rembourrage</strong> (coton cardé / ouate) protégeant <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">zones saillantes</span> (épicondyles, olécrane, styloïde ulnaire ; tête fibulaire, tubérosité tibiale, malléoles) et les <span class=\"kw-clinique\">zones vasculo-nerveuses</span> (pli du coude, gouttière épitrochléenne, creux poplité, col de la fibula)</li>\n        <li><strong>Bandes plâtrées</strong> appliquées <span class=\"kw-alerte\">sans tension mais sans pli</span>, renforcées sur <span class=\"kw-clinique\">les</span> zones de contrainte</li>\n        <li><strong>Solidité définitive</strong> non <span class=\"kw-etio\">acquise</span> avant <span class=\"kw-chiffre\">36 à 48 h</span> pour le plâtre, <span class=\"kw-chiffre\">quelques heures</span> pour la résine (abandonné trop tôt → fissuration, position vicieuse)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Règle de la fente immédiate.</strong> Après un traumatisme aigu, la confection d'une <span class=\"kw-alerte\">gouttière (attelle)</span> est la règle. Si un plâtre circulaire est posé, il doit être <span class=\"kw-alerte\">fendu immédiatement</span> d'une extrémité à l'autre jusqu'au jersey, berges légèrement écartées : pour ne pas laisser de bride compressive et permettre l'expansion de l'<span class=\"kw-clinique\">œdème</span>.</div>\n      <h4 class=\"kw-def\">Vérifications du plâtre fini</h4>\n      <ul>\n        <li><strong>Extrémités :</strong> ni coupantes ni appuyant sur la peau → <span class=\"kw-clinique\">les</span> <strong>éverser</strong> (ne pas recouper, ce qui déstabiliserait le plâtre)</li>\n        <li><strong>Pas trop serré :</strong> doigts/orteils s'étendent complètement, <span class=\"kw-clinique\">sensibilité</span> et <span class=\"kw-clinique\">coloration</span> normales</li>\n        <li><strong>Longueur :</strong> ne pas gêner la flexion des métacarpo-phalangiennes ou du genou (trop long), ni créer un appui trop court (souffrance cutanée)</li>\n        <li><strong>Contrôle <span class=\"kw-imagerie\">radiographique</span></strong> (face + profil) : <span class=\"kw-ttt\">réduction</span> correcte, position d'immobilisation, qualité — un <span class=\"kw-imagerie\">espace clair trop important</span> entre membre et plâtre = plâtre trop lâche</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 363 — Fractures fréquentes de l'adulte et du sujet âgé · 364 — Fractures de l'enfant</em></p>","frequence":0},{"id":"365-2","rang":"A","rubrique":"Diagnostic","titre":"Connaître les principales étiologies des douleurs sous plâtre","contenu":"<div class=\"callout callout-danger\"><strong>Dogme.</strong> <span class=\"kw-alerte\">Plâtre bien fait + absence de complication = PAS de douleur.</span> Toute douleur sous plâtre, surtout si elle augmente et résiste aux <span class=\"kw-ttt\">antalgiques</span>, doit faire évoquer une complication : <strong>aucune procrastination n'est permise</strong>.</div>\n      <p>Principales <span class=\"kw-etio\">étiologies</span> d'une douleur sous contention, à hiérarchiser de l'<span class=\"kw-alerte\">urgence</span> à la cause mécanique :</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Signes d'orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Syndrome des loges</strong></span> (compartimental)</td>\n            <td><span class=\"kw-clinique\">Douleur continue, non pulsatile, à type de brûlure/constriction</span>, disproportionnée, <span class=\"kw-alerte\">résistante à la morphine</span>, majorée à la <span class=\"kw-clinique\">mobilisation passive</span> ; <span class=\"kw-clinique\">cyanose des extrémités</span> (1er signe)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Ischémie de membre</strong></span> / plâtre trop serré</td>\n            <td>Extrémités <span class=\"kw-clinique\">décolorées, blanches, froides voire glacées</span> ; sensation de plâtre trop étroit ; <span class=\"kw-clinique\">paresthésies</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Compression nerveuse</span></td>\n            <td><span class=\"kw-clinique\">Engourdissement, picotements</span> puis déficit dans un territoire (fibulaire commun au <span class=\"kw-clinique\">col de la fibula</span> ++, ulnaire, médian, radial)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Escarre</span> sous plâtre</td>\n            <td>Douleur localisée sur un relief, <span class=\"kw-clinique\">fébricule</span>, <span class=\"kw-clinique\">odeur nauséabonde</span>, taches sur le plâtre (talon, coude)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Déplacement secondaire</span> de fracture</td>\n            <td><span class=\"kw-clinique\">Douleur secondaire</span> d'apparition retardée ; diagnostic sur la <span class=\"kw-imagerie\">radiographie de contrôle</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Phlébite</strong></span> (TVP) sous plâtre</td>\n            <td><span class=\"kw-clinique\">Douleur du mollet</span>, <span class=\"kw-clinique\">dissociation pouls-température</span>, fébricule, <span class=\"kw-clinique\">œdème</span> du dos du pied, <span class=\"kw-clinique\">cyanose</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">SDRC</span> de type 1 / <span class=\"kw-etio\">infection</span> (ostéite, <span class=\"kw-alerte\">arthrite septique</span> à évoquer en priorité sur <span class=\"kw-etio\">fracture ouverte articulaire</span> ou en <span class=\"kw-clinique\">post-opératoire</span> : douleur articulaire majeure, fièvre, épanchement/impotence — <span class=\"kw-ttt\">ponction articulaire en urgence</span>)</td>\n            <td>Douleur régionale traînante (SDRC) ; souillure du plâtre + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">adénopathies</span> (ostéite)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Hiérarchie.</strong> Le <span class=\"kw-alerte\">syndrome des loges</span> et l'<span class=\"kw-alerte\">ischémie de membre</span> sont <span class=\"kw-clinique\">les</span> urgences à éliminer en priorité devant toute douleur sous plâtre — avant d'évoquer une cause mécanique (plâtre trop serré, point d'appui).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 199 — Syndrome douloureux régional complexe · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":0},{"id":"365-3","rang":"A","rubrique":"Prise en charge","titre":"Savoir prévenir les complications à la mise en place d’une contention","contenu":"<p>La prévention commence dès la <span class=\"kw-def\">confection</span> et se poursuit par l'<strong>éducation</strong> du patient. Trois leviers : un plâtre bien fait, la lutte contre l'<span class=\"kw-clinique\">œdème</span>, la <span class=\"kw-ttt\">prophylaxie thromboembolique</span>.</p>\n      <h4 class=\"kw-def\">Confection prudente</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Gouttière</span> d'emblée après tout traumatisme aigu</strong> (<span class=\"kw-ci\">jamais de</span> plâtre circulaire fermé d'emblée) ; si plâtre circulaire → <span class=\"kw-alerte\">fendre immédiatement</span></li>\n        <li><span class=\"kw-clinique\">Rembourrage</span> des reliefs osseux et des trajets vasculo-nerveux ; bandes <strong>sans tension ni pli</strong></li>\n        <li><strong>Laisser libres doigts et orteils</strong> ; respecter la <span class=\"kw-def\">position de fonction</span> (coude jamais &gt; <span class=\"kw-chiffre\">90°</span> en BABP) ; pas de manche roulée faisant <span class=\"kw-alerte\">garrot</span> à la racine du membre</li>\n        <li>La <strong><span class=\"kw-ttt\">botte</span></strong> doit remonter <span class=\"kw-alerte\">au-dessus de la tête de la fibula</span> et non la dégager (le <span class=\"kw-clinique\">nerf fibulaire commun</span> passe sous le col)</li>\n      </ul>\n      <h4 class=\"kw-def\">Lutte contre l'<span class=\"kw-clinique\">œdème</span> (surtout <span class=\"kw-chiffre\">48-72 h</span>)</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Surélévation</span> du membre au-dessus du niveau du cœur (écharpe poignet &gt; coude au MS ; pieds du lit surélevés <span class=\"kw-chiffre\">5 à 10 cm</span> au MI)</li>\n        <li>Application de <span class=\"kw-ttt\">froid</span> au <span class=\"kw-def\">contact</span> du plâtre, sur une grande longueur</li>\n        <li><span class=\"kw-ttt\">Contractions isométriques</span> sous plâtre + mobilisation des articulations laissées libres (doigts, orteils)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Prophylaxie thromboembolique.</strong> <span class=\"kw-ttt\">HBPM</span> quotidienne <strong>dès que le patient est pubère</strong> pour <strong>tout plâtre du membre inférieur</strong> (appui autorisé ou non) et tout <span class=\"kw-ttt\">corset</span> pour fracture du rachis.</div>\n      <div class=\"callout callout-danger\"><strong>Suspicion clinique d'embolie pulmonaire.</strong> En cas de forte suspicion clinique d'<span class=\"kw-etio\">embolie pulmonaire</span> (dyspnée, douleur thoracique, désaturation / <span class=\"kw-alerte\">SaO2</span> basse) chez un patient plâtré ou immobilisé, débuter une <span class=\"kw-ttt\">anticoagulation curative empirique</span> (<span class=\"kw-ttt\">HBPM à dose curative</span>) <strong>sans attendre</strong> la confirmation par <span class=\"kw-imagerie\">angioTDM thoracique</span>, en l'absence de <span class=\"kw-ci\">contre-indication</span>.</div>\n      <h4 class=\"kw-def\">Éducation et <span class=\"kw-def\">surveillance</span> programmée</h4>\n      <ul>\n        <li>Enseigner <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes d'alarme</span> et les remettre par écrit (cf. conseils au porteur)</li>\n        <li>Garder le plâtre <strong>sec</strong> ; ne pas le vernir, le couper ni retirer le rembourrage</li>\n        <li>Consultations de <span class=\"kw-def\">suivi</span> avec <span class=\"kw-imagerie\">contrôle radiographique</span> à <span class=\"kw-chiffre\">J2, J8, J21, J45, J90</span> puis selon <span class=\"kw-clinique\">les</span> cas</li>\n      </ul>","frequence":0},{"id":"365-4","rang":"B","rubrique":"Définition","titre":"Connaître les principales dénominations des contentions","contenu":"<p>Le terme générique « <span class=\"kw-def\">plâtre</span> » désigne tout appareil d'immobilisation externe, sans préjuger du matériau (plâtre de Paris historique, désormais souvent <span class=\"kw-def\">résine</span>). On <span class=\"kw-clinique\">les</span> nomme par le <strong>segment immobilisé</strong>.</p>\n      <h4 class=\"kw-def\">Membre supérieur</h4>\n      <table >\n        <thead><tr><th>Dénomination</th><th>Étendue · immobilise</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Thoraco-brachial</span></td><td>Thorax + bras + avant-bras → <strong>épaule / humérus</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Brachio-anté-brachio-palmaire (BABP)</span></td><td>Bras + coude + avant-bras → <strong>coude</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Plâtre pendant</span></td><td>Fracture de l'humérus : effet de <span class=\"kw-clinique\">traction</span> par son propre poids (debout/assis) ; au lit, traction par ficelle + poids de <span class=\"kw-chiffre\">1 à 2 kg</span> dans l'axe</td></tr>\n          <tr><td><span class=\"kw-def\">Anté-brachio-palmaire</span> (« manchette »)</td><td>Avant-bras + poignet, libère <span class=\"kw-clinique\">les</span> MCP → <strong>poignet</strong></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Membre inférieur</h4>\n      <table >\n        <thead><tr><th>Dénomination</th><th>Étendue · immobilise</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Pelvi-dorso-pédieux (PDP)</span></td><td>Pelvis + tout le membre inférieur → <strong>hanche / fémur proximal</strong> (bermuda = 2 hanches ; hémi-bermuda = 1 hanche)</td></tr>\n          <tr><td><span class=\"kw-def\">Cruro-pédieux</span></td><td>Cuisse + genou + cheville</td></tr>\n          <tr><td><span class=\"kw-def\">Cruro-sus-malléolaire</span> (« genouillère »)</td><td>Appui patellaire, s'arrête au-dessus de la cheville</td></tr>\n          <tr><td><span class=\"kw-def\">Botte</span> (± « de marche »)</td><td>Tubérosité tibiale + malléoles → <strong>cheville</strong> ; remonte au-dessus de la tête fibulaire (<span class=\"kw-alerte\">nerf fibulaire commun</span>) ; appui autorisé si « botte de marche »</td></tr>\n          <tr><td><span class=\"kw-def\">Plâtre de Sarmiento</span></td><td>Diaphyse tibiale : immobilisation compressive du seul segment fracturé, mobilisation articulaire précoce, appui favorisant l'<span class=\"kw-bio\">ostéogenèse</span> ; en relais vers <span class=\"kw-chiffre\">21 jours</span>, <span class=\"kw-alerte\">risque de déplacement important</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Rachis</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Plâtre de Boehler</span> (« corset ») :</strong> appui sternum + sacrum + épines iliaques postéro-supérieures → rachis <strong>dorsal et lombaire</strong> ; posé seulement après <span class=\"kw-clinique\">reprise du transit</span> (<span class=\"kw-chiffre\">J3</span>-J4), <strong>fenêtré</strong> pour l'expansion gastrique</li>\n        <li><strong><span class=\"kw-def\">Minerve</span> :</strong> idem corset + appuis menton, front et occiput → rachis <strong>cervical, dorsal, lombaire</strong></li>\n      </ul>\n      <p>Selon la <strong>forme</strong> : <span class=\"kw-def\">plâtre circulaire</span> (entoure le membre) <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">gouttière</span> (moitié postérieure, ex. GPP).</p>","frequence":0},{"id":"365-5","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conseils à donner au porteur d’un plâtre","contenu":"<p>Le patient est un acteur de sa propre <span class=\"kw-def\">surveillance</span> : il faut lui <strong>expliquer et remettre par écrit</strong> <span class=\"kw-clinique\">les</span> signes qui imposent de <span class=\"kw-alerte\">consulter en urgence</span>.</p>\n      <h4 class=\"kw-def\">Signes d'alarme — contacter immédiatement un médecin</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Signaux</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Douleur</strong></td><td>Plâtre qui serre, douleur qui <span class=\"kw-clinique\">ne fait qu'augmenter</span>, qu'aucun <span class=\"kw-ttt\">antalgique</span> ne calme, sensation de brûlure / pression</td></tr>\n          <tr><td><strong>Neurologique</strong></td><td><span class=\"kw-clinique\">Engourdissement</span> ou <span class=\"kw-clinique\">picotements</span> des doigts/orteils, perte de la mobilité active</td></tr>\n          <tr><td><strong>Vasculaire</strong></td><td>Doigts/orteils <span class=\"kw-clinique\">décolorés, blancs, froids voire glacés</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">MTEV</span></strong></td><td><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">douleurs respiratoires</span>, <span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-alerte\">désaturation (SaO2)</span>, dyspnée ou douleur thoracique brutale évoquant une <span class=\"kw-etio\">embolie pulmonaire</span></td></tr>\n          <tr><td><strong>Infection</strong></td><td><span class=\"kw-clinique\">Taches sur le plâtre</span> + <span class=\"kw-clinique\">odeur nauséabonde</span></td></tr>\n          <tr><td><strong>Corset</strong></td><td><span class=\"kw-clinique\">Intolérance gastrique</span>, <span class=\"kw-clinique\">nausées</span> voire vomissements</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Conseils pratiques</h4>\n      <ul>\n        <li><strong>Limiter l'<span class=\"kw-clinique\">œdème</span></strong> (<span class=\"kw-chiffre\">48-72 h</span>) : pas de vêtement roulé en <span class=\"kw-alerte\">garrot</span>, <span class=\"kw-ttt\">froid</span> au <span class=\"kw-def\">contact</span>, <span class=\"kw-ttt\">surélévation</span> au-dessus du cœur, <span class=\"kw-ttt\">exercices</span> isométriques et mobilisation des articulations libres</li>\n        <li><strong>Protéger le plâtre :</strong> le garder <strong>sec</strong> (même la résine), ne pas le vernir (macération), ne pas couper <span class=\"kw-clinique\">les</span> bords ni retirer le rembourrage soi-même</li>\n        <li><strong>Tolérance cutanée :</strong> ne pas gratter <span class=\"kw-clinique\">les</span> démangeaisons ni glisser poudre/déodorant ; l'<span class=\"kw-clinique\">hypertrichose</span> régresse après ablation ; peau rouge ou à vif → consulter</li>\n        <li><strong>Marche / appui :</strong> attendre le séchage complet — <span class=\"kw-chiffre\">~1 h</span> (résine), <span class=\"kw-chiffre\">36 à 48 h</span> (plâtre)</li>\n        <li><strong>Conduite :</strong> <span class=\"kw-alerte\">interdiction de conduire</span> avec une immobilisation plâtrée</li>\n        <li><strong>Si corset :</strong> fractionner en <span class=\"kw-chiffre\">5 repas/j</span>, supprimer boissons gazeuses et chewing-gum (dilatation gastrique)</li>\n        <li><strong><span class=\"kw-ttt\">HBPM</span> quotidienne</strong> dès la puberté pour tout plâtre du MI et tout corset rachidien</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Ne jamais retirer le plâtre soi-même.</strong> Risque de couper la peau et d'<span class=\"kw-alerte\">empêcher la consolidation</span> : un os fracturé a besoin de plusieurs semaines à plusieurs mois pour se ressouder, même si la douleur s'arrête bien avant.</div>","frequence":0},{"id":"365-6","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir dépister et diagnostiquer une complication sous plâtre","contenu":"<p>La <span class=\"kw-def\">surveillance</span> dépiste <span class=\"kw-clinique\">les</span> complications par quelques signes simples : <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">œdème</span>, <span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">cyanose</span>, <span class=\"kw-clinique\">douleur à la mobilisation passive</span>. On les classe par appareil.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Complications · signes de <span class=\"kw-def\">dépistage</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Loco-régionale</strong></td>\n            <td><span class=\"kw-alerte\">Syndrome compartimental</span> : douleur disproportionnée résistante à la <span class=\"kw-ttt\">morphine</span>, majorée à la mobilisation passive, <span class=\"kw-clinique\">cyanose</span> distale (<span class=\"kw-alerte\">urgence</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaire</strong></td>\n            <td><span class=\"kw-alerte\">Ischémie</span> : extrémités froides, pâles, <span class=\"kw-clinique\">abolition des pouls</span> (<span class=\"kw-alerte\">urgence</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Compression nerveuse</strong></td>\n            <td>Déficit sensitivomoteur d'un territoire : <span class=\"kw-clinique\">fibulaire commun</span> (col de la fibula), <span class=\"kw-clinique\">ulnaire</span> (gouttière épitrochléo-olécrânienne), <span class=\"kw-clinique\">médian</span> (pli du coude, poignet), <span class=\"kw-clinique\">radial</span> (diaphyse humérale, <span class=\"kw-chiffre\">10 cm au-dessus du coude</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Cutanée / infectieuse</strong></td>\n            <td><span class=\"kw-etio\">Escarre</span> (douleur, fébricule, <span class=\"kw-clinique\">adénopathies</span>, odeur, taches) → <span class=\"kw-etio\">arthrite</span>, <span class=\"kw-etio\">ostéite</span> (souillure du plâtre, <span class=\"kw-clinique\">fièvre</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombo-<span class=\"kw-etio\">embolique</span></strong></td>\n            <td><span class=\"kw-alerte\">TVP / EP</span> : douleur du mollet, <span class=\"kw-clinique\">dissociation pouls-température</span>, <span class=\"kw-clinique\">œdème</span> du dos du pied, <span class=\"kw-clinique\">cyanose</span> ; dyspnée/hémoptysie (EP)</td>\n          </tr>\n          <tr>\n            <td><strong>Efficacité du plâtre</strong></td>\n            <td>Plâtre devenu <span class=\"kw-clinique\">trop lâche</span> (résorption de l'<span class=\"kw-clinique\">œdème</span>, amyotrophie) : descend à la traction, orteils/doigts disparaissent, <span class=\"kw-imagerie\">espace clair</span> en RX</td>\n          </tr>\n          <tr>\n            <td><strong>Déplacement</strong></td>\n            <td><span class=\"kw-clinique\">Douleur secondaire</span> ; diagnostic sur la <span class=\"kw-imagerie\">RX de contrôle</span> (à prescrire « <strong>AVEC plâtre</strong> »)</td>\n          </tr>\n          <tr>\n            <td><strong>Ostéo-articulaire</strong></td>\n            <td><span class=\"kw-clinique\">Raideur</span>, <span class=\"kw-bio\">ostéoporose</span> transitoire de non-usage, <span class=\"kw-etio\">SDRC</span> de type 1</td>\n          </tr>\n          <tr>\n            <td><strong>Selon le type de plâtre</strong></td>\n            <td><span class=\"kw-clinique\">Gêne respiratoire</span> (thoraco-abdominal, coude au corps) ; entrave de la dilatation gastrique / <span class=\"kw-clinique\">occlusion fonctionnelle</span> (corsets, PDP)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Les</span> deux urgences vitales / fonctionnelles à dépister en priorité :</strong> le <span class=\"kw-alerte\">syndrome des loges</span> et les <span class=\"kw-alerte\">complications thromboemboliques</span>. <span class=\"kw-def\">Surveillance</span> essentielle : douleur, <span class=\"kw-clinique\">œdème</span>, paresthésies, <span class=\"kw-clinique\">cyanose</span>, douleur à la mobilisation passive.</div>\n      <div class=\"callout callout-warn\"><strong>Piège d'ordonnance.</strong> Écrire « <span class=\"kw-imagerie\">radiographie AVEC plâtre</span> » et jamais « sous plâtre », qui peut être lu « <strong>sans</strong> plâtre ».</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 120 — Complications immobilité - décubitus · 199 — Syndrome douloureux régional complexe · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":1},{"id":"365-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","contenu":"<p>Devant toute suspicion de complication, le principe est commun : <strong>lever la contrainte sans délai</strong>, puis traiter la cause. <span class=\"kw-alerte\">Toute procrastination est interdite.</span></p>\n      <h4 class=\"kw-def\">Geste réflexe — décomprimer</h4>\n      <ul>\n        <li><strong>Fendre le plâtre</strong> (bivalve), voire <span class=\"kw-alerte\">l'enlever</span> dès la suspicion d'une <span class=\"kw-alerte\">urgence</span> loco-régionale, vasculaire, nerveuse ou thromboembolique</li>\n        <li><strong>Surélever</strong> le membre et réévaluer rapidement (sensibilité, motricité, coloration, pouls)</li>\n      </ul>\n      <h4 class=\"kw-def\">Conduites spécifiques</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Syndrome des loges</span></td><td>Ablation du plâtre + <span class=\"kw-ttt\">aponévrotomie (fasciotomie)</span> en <span class=\"kw-alerte\">urgence</span> (&lt; <span class=\"kw-chiffre\">6 h</span>) de toutes <span class=\"kw-clinique\">les</span> loges</td></tr>\n          <tr><td><span class=\"kw-alerte\">Ischémie de membre</span></td><td>Ablation immédiate de la contention + avis <span class=\"kw-ttt\">chirurgical vasculaire</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">revascularisation</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Compression nerveuse</span></td><td><strong>Ablation du plâtre</strong> et réfection sans compression</td></tr>\n          <tr><td><span class=\"kw-etio\">Escarre</span> / <span class=\"kw-etio\">ostéite</span></td><td>Découper une <strong>fenêtre</strong> pour soins locaux (escarre) ; ablation + <span class=\"kw-bio\">prélèvements bactério</span> + mise à plat ± <span class=\"kw-ttt\">ATB</span> ± fixateur externe (ostéite)</td></tr>\n          <tr><td><span class=\"kw-alerte\">TVP / EP</span></td><td>Plâtre coupé en bivalve voire enlevé, <span class=\"kw-bio\">écho-doppler veineux</span>, <span class=\"kw-ttt\">anticoagulation curative</span> immédiate</td></tr>\n          <tr><td>Plâtre <span class=\"kw-clinique\">trop lâche</span></td><td><span class=\"kw-ttt\">Circularisation</span> d'une attelle ou réfection complète de l'immobilisation</td></tr>\n          <tr><td><span class=\"kw-etio\">Déplacement</span> secondaire</td><td><span class=\"kw-ttt\">Gypsotomie</span> (correction sans anesthésie) ou <span class=\"kw-ttt\">réduction</span> sous AG ± <span class=\"kw-ttt\">ostéosynthèse</span> — à dépister <strong>avant la 3ᵉ semaine</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Occlusion</span> sur corset</td><td><span class=\"kw-ttt\">Aspiration gastrique par sonde</span> en <span class=\"kw-alerte\">urgence</span> jusqu'à régression</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Gypsotomie.</strong> Section circulaire subtotale du plâtre au niveau de la déformation (charnière conservée à l'opposé) → on fait bâiller la tranche, on cale en position corrigée, puis on referme après contrôle <span class=\"kw-imagerie\">radiographique</span> satisfaisant.</div>","frequence":0},{"id":"365-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge en urgence d’une ischémie de membre sous contention","contenu":"<p>Une <span class=\"kw-alerte\">ischémie de membre</span> sous plâtre résulte d'une <span class=\"kw-etio\">compression</span> (plâtre trop serré) ou d'une <span class=\"kw-etio\">lésion vasculaire</span>. C'est une <span class=\"kw-alerte\">urgence</span> : le <span class=\"kw-def\">pronostic</span> du membre se joue en quelques heures.</p>\n      <h4 class=\"kw-def\">Reconnaître</h4>\n      <ul>\n        <li>Extrémités <span class=\"kw-clinique\">pâles / décolorées, froides voire glacées</span></li>\n        <li><span class=\"kw-clinique\">Abolition des pouls distaux</span>, <span class=\"kw-clinique\">paresthésies</span> puis déficit moteur</li>\n        <li>Douleur, sensation de plâtre trop étroit</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Distinction clé.</strong> Dans le <span class=\"kw-alerte\">syndrome des loges</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">pouls périphériques</span> sont longtemps <strong>perçus</strong>. Une <span class=\"kw-alerte\">abolition des pouls</span> doit faire suspecter une <strong><span class=\"kw-clinique\">lésion</span> vasculaire</strong>, elle-même responsable d'un syndrome compartimental par ischémie.</div>\n      <h4 class=\"kw-def\">Prise en charge en <span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li><strong>Ablation immédiate de la contention</strong> (fendre en bivalve puis enlever) pour lever toute bride compressive</li>\n        <li><span class=\"kw-ttt\">Surélévation</span> et <span class=\"kw-def\">réévaluation</span> de la recoloration, des pouls et de la sensibilité</li>\n        <li>Si pas de régression rapide → <strong>avis chirurgical vasculaire en <span class=\"kw-alerte\">urgence</span></strong> (recherche et levée de l'obstacle, <span class=\"kw-ttt\">revascularisation</span>) et recherche d'un syndrome des loges associé (<span class=\"kw-ttt\">aponévrotomie</span>)</li>\n      </ul>","frequence":0},{"id":"365-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge en urgence d’un syndrome des loges","contenu":"<p>Le <span class=\"kw-def\">syndrome des loges</span> (compartimental) est une <span class=\"kw-alerte\">hyperpression</span> dans une loge musculaire <strong>inextensible</strong> (fascia), qui entrave le <span class=\"kw-ttt\">drainage</span> veineux et la microcirculation → <span class=\"kw-alerte\">ischémie myocytaire</span> et nerveuse, cercle vicieux menaçant la viabilité du membre.</p>\n      <h4 class=\"kw-def\">Causes et <span class=\"kw-def\">facteurs de risque</span></h4>\n      <ul>\n        <li><strong>Cause principale :</strong> <span class=\"kw-etio\">fracture</span> (hématome + <span class=\"kw-clinique\">œdème</span> dans la loge) ; aussi contusion, <span class=\"kw-etio\">plâtre/pansement trop serré</span>, brûlures circonférentielles, fasciites nécrosantes</li>\n        <li><strong>FDR :</strong> traumatisme à <span class=\"kw-clinique\">haute énergie</span>, <span class=\"kw-clinique\">fracture déplacée</span>, fracture fermée du 1/3 supérieur de jambe, enclouage centro-médullaire</li>\n      </ul>\n      <h4 class=\"kw-def\">Diagnostic clinique (4 P)</h4>\n      <div class=\"callout callout-warn\"><strong>4 P :</strong> <span class=\"kw-clinique\">pain</span> · <span class=\"kw-clinique\">pain with passive stretch</span> (douleur à l'étirement passif) · <span class=\"kw-clinique\">paresthésies</span> · <span class=\"kw-clinique\">parésie</span>. Signes peu spécifiques, apparition parfois retardée de quelques heures à quelques jours.</div>\n      <ul>\n        <li><strong>Douleur pathognomonique :</strong> <span class=\"kw-clinique\">continue, non pulsatile, à type de brûlure/constriction</span>, disproportionnée, <span class=\"kw-alerte\">résistante à la morphine</span>, majorée à la <span class=\"kw-clinique\">mobilisation passive</span>, à la palpation des masses tendues et à la contraction</li>\n        <li><strong>1er signe :</strong> <span class=\"kw-clinique\">cyanose des extrémités</span> ; membre turgescent, peau évoluant vers l'aspect <span class=\"kw-clinique\">marbré</span> puis phlycténulaire</li>\n        <li><strong><span class=\"kw-clinique\">Pouls périphériques</span> perçus</strong> (leur abolition = suspecter une <span class=\"kw-clinique\">lésion</span> vasculaire)</li>\n        <li><strong>Déficit sensitivomoteur</strong> du nerf de la loge : ex. <span class=\"kw-clinique\">hypoesthésie de la 1ʳᵉ commissure dorsale + paralysie de l'hallux</span> = atteinte du <span class=\"kw-clinique\">nerf fibulaire profond</span> (signe pathognomonique)</li>\n        <li><strong>Signes trop tardifs :</strong> <span class=\"kw-alerte\">pâleur, disparition des pouls distaux</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Confirmation (ne doit pas retarder le traitement) :</strong> mesure de la <span class=\"kw-bio\">pression des loges</span> — normale &lt; <span class=\"kw-chiffre\">10 mmHg</span>, pathologique &gt; <span class=\"kw-chiffre\">30 mmHg</span> ; pression différentielle (<span class=\"kw-bio\">PAD − pression de loge</span>) &lt; <span class=\"kw-chiffre\">30 mmHg</span> fait le diagnostic.</div>\n      <h4 class=\"kw-def\">Traitement — <span class=\"kw-alerte\">urgence</span> absolue</h4>\n      <ul>\n        <li><strong>En présence d'un plâtre :</strong> l'<span class=\"kw-alerte\">enlever immédiatement</span> (ou fente) dès la suspicion ; si pas de régression en <span class=\"kw-chiffre\">&lt; 3-4 h</span>, diagnostic très probable</li>\n        <li><strong><span class=\"kw-ttt\">Aponévrotomie (fasciotomie)</span> en <span class=\"kw-alerte\">urgence</span>, &lt; <span class=\"kw-chiffre\">6 h</span></strong> : <strong>toutes <span class=\"kw-clinique\">les</span> loges</strong> ouvertes (incision médiale → loges postérieures ; incision latérale → loges antérieure et externe)</li>\n        <li><strong>Suites :</strong> peau laissée ouverte, refermée après quelques jours (fonte de l'<span class=\"kw-clinique\">œdème</span>), pansements / 2 j ± excision des nécroses</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Si traitement trop tardif :</strong> <span class=\"kw-clinique\">nécrose</span> musculaire irréversible → <span class=\"kw-alerte\">rétractions tendineuses</span> et déformations (griffe des orteils au MI ; <span class=\"kw-def\">syndrome de Volkmann</span> au MS : flexion du poignet, hyperextension des MCP, flexion des phalanges).</div>","frequence":0},{"id":"365-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge en urgence d’une thrombose veineuse sous contention","contenu":"<p>La <span class=\"kw-alerte\">phlébite sous plâtre</span> est fréquente et souvent <span class=\"kw-clinique\">infraclinique</span>, malgré la prévention systématique par <span class=\"kw-ttt\">HBPM</span> (plâtre du MI, corset rachidien) ; elle peut aboutir à une <span class=\"kw-alerte\">embolie pulmonaire</span>.</p>\n      <h4 class=\"kw-def\">Suspecter une TVP sous plâtre</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur du mollet</span> sous plâtre</li>\n        <li><span class=\"kw-clinique\">Dissociation pouls-température</span> (pouls augmenté plus que ne le voudrait la température)</li>\n        <li><span class=\"kw-clinique\">Fébricule</span>, <span class=\"kw-clinique\">œdème du dos du pied</span>, <span class=\"kw-clinique\">cyanose des extrémités</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Examen impossible sous plâtre.</strong> On ne peut rechercher ni le <span class=\"kw-clinique\">choc rotulien</span> ni le <span class=\"kw-clinique\">signe de Homans</span> (et il ne faut pas le chercher : risque de <span class=\"kw-alerte\">déplacement de fracture</span>).</div>\n      <h4 class=\"kw-def\">Conduite à tenir</h4>\n      <ul>\n        <li>Plâtre <strong>coupé en bivalve, voire enlevé</strong></li>\n        <li>Examen du mollet <strong>sans recherche du signe de Homans</strong></li>\n        <li><span class=\"kw-bio\">Écho-doppler veineux</span> (± phlébographie pour certaines formes proximales)</li>\n        <li><strong><span class=\"kw-ttt\">Anticoagulation curative</span> immédiate</strong></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Suspicion d'<span class=\"kw-alerte\">embolie pulmonaire</span> :</strong> <span class=\"kw-clinique\">anxiété, douleur thoracique, hémoptysie, détresse respiratoire</span> → <span class=\"kw-imagerie\">angio-TDM</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">anticoagulation</span> curative.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/deep-vein-thrombosis","label":"Radiopaedia : Deep Vein Thrombosis"},{"href":"https://radiopaedia.org/articles/superficial-thrombophlebitis","label":"Radiopaedia : Superficial Thrombophlebitis"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> le <span class=\"kw-alerte\">syndrome compartimental</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications thrombo-emboliques</span> sont des <span class=\"kw-alerte\">urgences médicales</span> — toute procrastination est <span class=\"kw-ci\">interdite</span>.<br><strong>Fenêtre :</strong> prise en charge du <span class=\"kw-etio\">syndrome des loges</span> en <span class=\"kw-chiffre\">moins de 6 h</span> (lésions irréversibles au-delà) ; régression des symptômes attendue <span class=\"kw-chiffre\">en moins de 3-4 h</span> après levée de la compression.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">ôter ou fendre le plâtre en bivalve</span> dès la suspicion, puis examiner le membre.</p>","hospit":"<p><strong>Sur place :</strong> devant toute douleur anormale, <span class=\"kw-ttt\">lever la contention</span> (fente ou ablation) avant tout examen complémentaire.<br><strong>Bloc opératoire :</strong> suspicion de <span class=\"kw-etio\">syndrome des loges</span> → <span class=\"kw-ttt\">aponévrotomie en urgence</span> ; la <span class=\"kw-bio\">mesure des pressions de loge</span> ne doit pas retarder le traitement.<br><strong><span class=\"kw-alerte\">Urgence</span> vasculaire :</strong> <span class=\"kw-alerte\">abolition des pouls distaux</span> → suspecter une <span class=\"kw-etio\">lésion vasculaire</span> imposant un avis spécialisé urgent.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Douleur continue, constrictive ou à type de brûlure</span>, disproportionnée au traumatisme et <span class=\"kw-alerte\">résistant à la morphine</span></li><li>Majoration de la douleur à la <span class=\"kw-clinique\">mobilisation passive</span> (4P : <span class=\"kw-clinique\">pain, pain with passive stretch, paresthésies, parésie</span>)</li><li><span class=\"kw-alerte\">Cyanose des extrémités</span> (1er signe du syndrome des loges)</li><li><span class=\"kw-clinique\">Hypoesthésie de la 1re commissure dorsale + paralysie de l'hallux</span> (atteinte du <span class=\"kw-etio\">nerf fibulaire profond</span>, quasi pathognomonique)</li><li>Orteils ou doigts <span class=\"kw-alerte\">décolorés, blancs, froids voire glacés</span> ; <span class=\"kw-alerte\">pâleur et disparition des pouls distaux</span> (signes tardifs)</li><li><span class=\"kw-clinique\">Engourdissement, picotements</span> et perte de la mobilité active des doigts ou des orteils</li><li><span class=\"kw-clinique\">Douleur du mollet</span>, <span class=\"kw-clinique\">fébricule</span>, <span class=\"kw-clinique\">dissociation pouls-température</span>, <span class=\"kw-clinique\">œdème du dos du pied</span> (suspicion de <span class=\"kw-etio\">TVP</span>)</li><li><span class=\"kw-clinique\">Anxiété, douleur thoracique, hémoptysie, détresse respiratoire</span> (suspicion d'<span class=\"kw-etio\">embolie pulmonaire</span>)</li><li><span class=\"kw-clinique\">Taches sur le plâtre + odeur nauséabonde</span> et <span class=\"kw-clinique\">fièvre</span> (<span class=\"kw-etio\">escarre / ostéite</span>)</li><li><span class=\"kw-clinique\">Intolérance gastrique, nausées ou vomissements</span> chez le porteur d'un corset (<span class=\"kw-etio\">occlusion fonctionnelle</span>)</li></ul>","principes":"<p>Toute complication impose de <span class=\"kw-ttt\">lever la contention</span>, puis de traiter l'étiologie sans délai.</p><p><strong>Syndrome des loges (compartimental)</strong></p><p>Incision médiale (loges postérieures profonde et superficielle) + incision latérale (loge antérieure et loge externe)</p><ul><li><span class=\"kw-ttt\">Ablation ou fente du plâtre</span> immédiate ; si pas de régression <span class=\"kw-chiffre\">en moins de 3-4 h</span> → diagnostic très vraisemblable</li><li><span class=\"kw-bio\">Pression de loge supérieure à 30 mmHg</span> ou différentielle <span class=\"kw-bio\">(PAD − pression de loge) inférieure à 30 mmHg</span></li><li><span class=\"kw-ttt\">Aponévrotomie (fasciotomie) de toutes les loges</span> en <span class=\"kw-alerte\">urgence</span>, délai <span class=\"kw-chiffre\">inférieur à 6 h</span></li></ul><p><strong>Ischémie de membre</strong></p><ul><li><span class=\"kw-alerte\">Pouls distaux abolis</span> → suspecter une <span class=\"kw-etio\">lésion vasculaire</span> (elle-même cause de syndrome compartimental par ischémie)</li><li><span class=\"kw-ttt\">Lever la contention</span> en <span class=\"kw-alerte\">urgence</span> et avis vasculaire immédiat</li></ul><p><strong>Thrombose veineuse / <span class=\"kw-alerte\">embolie pulmonaire</span></strong></p><p>Prévention : <span class=\"kw-ttt\">HBPM</span> systématique pour tout plâtre du membre inférieur et tout corset, dès la puberté</p><ul><li><span class=\"kw-ttt\">Couper le plâtre en bivalve</span> voire l'ôter, puis examiner le mollet <span class=\"kw-ci\">sans rechercher le signe de Homans</span> (risque de déplacement)</li><li><span class=\"kw-imagerie\">Écho-doppler veineux</span> ; <span class=\"kw-imagerie\">angio-TDM</span> en <span class=\"kw-alerte\">urgence</span> si suspicion d'<span class=\"kw-etio\">embolie pulmonaire</span></li><li><span class=\"kw-ttt\">Anticoagulation curative immédiate</span></li></ul><p><strong>Complications cutanées et infectieuses</strong></p><ul><li>Escarre : <span class=\"kw-ttt\">découpe d'une fenêtre</span> dans le plâtre pour réaliser des <span class=\"kw-ttt\">soins locaux</span></li><li><span class=\"kw-etio\">Ostéite</span> : <span class=\"kw-ttt\">ablation du plâtre, prélèvements bactériologiques, mise à plat, antibiothérapie</span> ; <span class=\"kw-ttt\">fixateur externe</span> si infection trop sérieuse</li></ul>","suivi":"<p><strong>Rythme :</strong> consultations de <span class=\"kw-def\">suivi</span> avec <span class=\"kw-imagerie\">RX de face + profil</span> à <span class=\"kw-chiffre\">J2, J8, J21, J45, J90</span> puis <span class=\"kw-chiffre\">tous les mois</span>.<br><strong>À surveiller :</strong> <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">œdème</span>, <span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">cyanose</span> et <span class=\"kw-clinique\">douleur à la mobilisation passive</span>.<br><strong>Déplacement :</strong> à dépister <span class=\"kw-chiffre\">avant la fin de la 3e semaine</span> (ordonnance « RX AVEC plâtre ») pour permettre une nouvelle <span class=\"kw-ttt\">réduction</span> facile.<br><strong>Prévention MTEV :</strong> <span class=\"kw-ttt\">HBPM</span> quotidienne pour tout plâtre du membre inférieur et corset, dès la puberté.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/superficial-thrombophlebitis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/deep-vein-thrombosis","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Symptôme nouveau sous plâtre — Plâtre bien fait + sans complication = pas de douleur","detail":"<h4>CAT — Complication sous plâtre — Devant tout symptôme nouveau sous contention plâtrée</h4>","branches":[{"to":"q1","label":"Lever la contention puis examiner","color":"blue"}]},{"id":"q1","kind":"decision","label":"Douleur ischémique disproportionnée, majorée à la mobilisation passive, avec cyanose des extrémités ? — 4P : douleur, douleur à l'étirement passif, paresthésies, parésie","branches":[{"to":"q-pouls","label":"Oui (4P + cyanose)","color":"red"},{"to":"q2","label":"Non","color":"blue"}]},{"id":"q-pouls","kind":"decision","label":"Pouls périphériques distaux perçus ?","branches":[{"to":"t-loges","label":"Pouls perçus","color":"red"},{"to":"t-ischemie","label":"Pouls distaux abolis","color":"red"}]},{"id":"t-loges","kind":"terminal","label":"Syndrome des loges — aponévrotomie en urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Douleur continue, constrictive, disproportionnée</span> résistant à la <span class=\"kw-ttt\">morphine</span>, majorée à la <span class=\"kw-clinique\">mobilisation passive</span></li><li><span class=\"kw-clinique\">Cyanose des extrémités</span> (1er signe) ; <span class=\"kw-alerte\">pouls périphériques perçus</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Pression de loge supérieure à 30 mmHg</span> ou différentielle <span class=\"kw-bio\">(PAD − pression) inférieure à 30 mmHg</span></li><li>La mesure ne doit pas retarder le geste</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ablation / fente du plâtre</span> immédiate</li><li><span class=\"kw-ttt\">Aponévrotomie de toutes les loges</span> (incision médiale + latérale)</li></ul><h4>Délai</h4><ul><li><span class=\"kw-alerte\">Moins de 6 h</span>, sinon <span class=\"kw-clinique\">nécrose</span> musculaire et <span class=\"kw-etio\">rétractions tendineuses</span> (<span class=\"kw-clinique\">syndrome de Volkmann</span>)</li></ul>"},{"id":"t-ischemie","kind":"terminal","label":"Ischémie de membre — urgence vasculaire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Pâleur</span>, extrémités <span class=\"kw-clinique\">froides et blanches</span>, <span class=\"kw-alerte\">pouls distaux abolis</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Lever la contention</span> en <span class=\"kw-alerte\">urgence</span></li><li>Suspecter une <span class=\"kw-etio\">lésion vasculaire</span> → avis vasculaire immédiat</li></ul>"},{"id":"q2","kind":"decision","label":"Douleur du mollet, fébricule, ou signes respiratoires (dyspnée, hémoptysie) ?","branches":[{"to":"t-mtev","label":"Oui (mollet / dyspnée)","color":"red"},{"to":"t-surveillance","label":"Non — pas de signe vital","color":"amber"}]},{"id":"t-mtev","kind":"terminal","label":"Suspicion de TVP / embolie pulmonaire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur du mollet</span>, <span class=\"kw-clinique\">fébricule</span>, <span class=\"kw-clinique\">dissociation pouls-température</span>, <span class=\"kw-clinique\">œdème du dos du pied</span></li><li>EP : <span class=\"kw-clinique\">douleur thoracique</span>, <span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-clinique\">détresse respiratoire</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Écho-doppler veineux</span> (examen du mollet <span class=\"kw-ci\">sans recherche du signe de Homans</span>)</li><li><span class=\"kw-imagerie\">Angio-TDM</span> si suspicion d'<span class=\"kw-etio\">embolie pulmonaire</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Couper le plâtre en bivalve</span> puis <span class=\"kw-ttt\">anticoagulation curative immédiate</span></li></ul>"},{"id":"t-surveillance","kind":"terminal","label":"Pas de signe vital — rechercher escarre / infection / déplacement","color":"amber","detail":"<h4>Conduite</h4><ul><li>Rechercher <span class=\"kw-clinique\">taches sur le plâtre</span> et <span class=\"kw-clinique\">odeur nauséabonde</span> (<span class=\"kw-etio\">escarre / ostéite</span>) → <span class=\"kw-ttt\">fenêtre + soins locaux</span></li><li>Dépister un <span class=\"kw-etio\">plâtre trop lâche</span> ou un <span class=\"kw-etio\">déplacement secondaire</span> par <span class=\"kw-imagerie\">RX face + profil</span> (avant fin de 3e semaine)</li><li>Adapter l'immobilisation et poursuivre la <span class=\"kw-ttt\">surveillance</span></li></ul>"}]},"cards":[{"i":"380368db08c2","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Dans quel cas la 'règle de la fente immédiate' doit-elle être appliquée pour un plâtre circulaire, et pourquoi ?","a":"<p>Après un <strong>traumatisme aigu</strong>, si un plâtre circulaire est posé, il doit être <strong>fendu immédiatement</strong> d'une extrémité à l'autre jusqu'au jersey, avec les berges légèrement écartées. Cette mesure est indispensable pour <strong>éviter toute bride compressive</strong> et permettre l'<strong>expansion de l'œdème</strong> post-traumatique, prévenant ainsi un syndrome de loges.</p>"},{"i":"69770fa7d4b3","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Quelle est la définition et la finalité d'une contention plâtrée ou en résine selon les principes de réalisation ?","a":"<p>Une contention plâtrée ou en résine vise à <strong>maintenir sans danger une articulation ou un segment de squelette</strong> jusqu'à la <strong>consolidation des lésions</strong>. Le médecin en assume la responsabilité, même si sa réalisation est effectuée par un auxiliaire.</p>"},{"i":"7050739660ae","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Quelles sont les étapes préparatoires cruciales et les précautions à prendre lors de la réalisation d'une contention plâtrée ?","a":"<ul><li><strong>Avant la pose</strong> : Retirer bagues et anneaux, proscrire tout pansement circulaire sous le plâtre. La peau doit être lavée et séchée, recouverte d'un <strong>jersey tubulaire sans pli</strong>.</li><li><strong>Rembourrage</strong> : Utiliser du coton cardé ou de l'ouate pour protéger les <strong>zones saillantes</strong> (épicondyles, olécrane, malléoles) et les <strong>zones vasculo-nerveuses</strong> (pli du coude, creux poplité).</li><li><strong>Application des bandes</strong> : Appliquer sans tension et sans pli, avec un renforcement sur les zones de contrainte.</li><li><strong>Solidité</strong> : La solidité définitive n'est acquise qu'après <strong>36 à 48 heures pour le plâtre</strong>, quelques heures pour la résine.</li></ul>"},{"i":"7f1749a90426","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Quelles vérifications essentielles doivent être faites sur une contention plâtrée finie ?","a":"<ul><li><strong>Extrémités</strong> : Elles ne doivent être ni coupantes ni appuyant sur la peau (les éverser sans couper).</li><li><strong>Serrage</strong> : Le plâtre ne doit pas être trop serré, permettant l'extension complète des doigts/orteils, avec une sensibilité et une coloration normales.</li><li><strong>Longueur</strong> : La longueur doit être adéquate pour ne pas gêner la flexion des articulations ou créer un appui trop court provoquant des souffrances cutanées.</li><li><strong>Contrôle radiographique</strong> : Il doit confirmer la réduction correcte, la position d'immobilisation et l'absence d'un espace clair trop important entre le membre et le plâtre (signe de plâtre lâche).</li></ul>"},{"i":"e19cc991c9e6","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Quelles sont les indications principales pour la pose d'une contention plâtrée/résine, en distinguant les types de traitements ?","a":"<ul><li>En <strong>traitement orthopédique seul</strong> : pour une immobilisation directe, ou après réduction d'une fracture par manœuvre externe, ou après réduction d'une entorse ou luxation.</li><li>En <strong>complément d'une chirurgie</strong> : après ostéosynthèse à foyer ouvert.</li></ul>"},{"i":"f29a4ca66755","n":365,"o":"365-1","u":"Prise en charge","t":"Connaître les principes de réalisation d’une contention plâtrée/résine","q":"Quels sont les principes d'étendue et de positionnement à respecter lors de la confection d'une contention plâtrée ?","a":"<ul><li><strong>Étendue</strong> : Pour une fracture, il faut immobiliser les <strong>articulations sus- et sous-jacentes</strong>. Pour une articulation, les <strong>pièces osseuses sus- et sous-jacentes</strong>. Toujours laisser <strong>libres les doigts et orteils</strong> pour permettre leur mobilisation et la surveillance (sensibilité/motricité).</li><li><strong>Position du membre</strong> : Maintenir en <strong>position de fonction</strong> et proscrire les positions extrêmes (ex: membre supérieur: coude à 90° de flexion, pro-supination intermédiaire, poignet en extension neutre, pouce en opposition ; membre inférieur: genou à 10° de flexion, cheville à 90°).</li></ul>"},{"i":"11c49a3fffca","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quelle est l'attitude à adopter face à toute douleur sous plâtre ?","a":"<p>Toute douleur sous plâtre, surtout si elle augmente et résiste aux antalgiques, doit faire évoquer une complication. <strong>Aucune procrastination n'est permise</strong>.</p>"},{"i":"2ba7183197e1","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quels signes cliniques orientent vers une compression nerveuse comme cause de douleur sous plâtre ?","a":"<p>Des <strong>engourdissements</strong>, des <strong>picotements</strong>, puis un <strong>déficit</strong> dans un territoire spécifique (particulièrement le nerf <strong>fibulaire commun au col de la fibula</strong>, ulnaire, médian ou radial).</p>"},{"i":"418731cbab9b","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Comment différencier une phlébite (TVP) sous plâtre des autres causes de douleur ?","a":"<p>Une phlébite sous plâtre se manifeste par une <strong>douleur du mollet</strong>, une <strong>dissociation pouls-température</strong>, une <strong>fébricule</strong>, un <strong>œdème du dos du pied</strong> et une cyanose.</p>"},{"i":"63a305a123e9","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quels signes cliniques orientent vers une ischémie de membre ou un plâtre trop serré comme cause de douleur sous plâtre ?","a":"<ul><li>Des extrémités <strong>décolorées, blanches, froides voire glacées</strong>.</li><li>Une sensation de plâtre trop étroit.</li><li>Des paresthésies.</li></ul>"},{"i":"776dabcbc16d","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quels signes cliniques orientent vers un syndrome des loges comme cause de douleur sous plâtre ?","a":"<ul><li>Une douleur continue, non pulsatile, à type de <strong>brûlure/constriction</strong>.</li><li>Elle est <strong>disproportionnée</strong> et <strong>résistante à la morphine</strong>.</li><li>Elle est majorée à la mobilisation passive.</li><li>La <strong>cyanose des extrémités</strong> est le premier signe à rechercher.</li></ul>"},{"i":"8e5fe930ecc8","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quelles sont les deux principales urgences à éliminer en priorité devant une douleur sous plâtre ?","a":"<ul><li>Le <strong>syndrome des loges</strong>.</li><li>L'<strong>ischémie de membre</strong>.</li></ul>"},{"i":"c93aa5b96950","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quels signes cliniques orientent vers une escarre sous plâtre comme cause de douleur ?","a":"<ul><li>Une <strong>douleur localisée</strong> sur un relief osseux.</li><li>Une <strong>fébricule</strong>.</li><li>Une <strong>odeur nauséabonde</strong>.</li><li>Des <strong>taches</strong> sur le plâtre, notamment au niveau du talon ou du coude.</li></ul>"},{"i":"d5ba3e41c506","n":365,"o":"365-2","u":"Diagnostic","t":"Connaître les principales étiologies des douleurs sous plâtre","q":"Quelles sont les étiologies plus rares de douleurs sous plâtre, au-delà des urgences et causes mécaniques ?","a":"<ul><li>Le <strong>déplacement secondaire de fracture</strong> (douleur secondaire d'apparition retardée, diagnostic radiographique).</li><li>Le <strong>Syndrome Douloureux Régional Complexe (SDRC) de type 1</strong> (douleur régionale traînante).</li><li>Une <strong>infection (ostéite)</strong> se manifestant par une souillure du plâtre, de la fièvre et des adénopathies.</li></ul>"},{"i":"30f8f71bf21c","n":365,"o":"365-3","u":"Prise en charge","t":"Savoir prévenir les complications à la mise en place d’une contention","q":"Quels sont les éléments essentiels de l'éducation du patient et de la surveillance après la pose d'un plâtre ?","a":"<ul><li>Enseigner les <strong>signes d'alarme</strong> et les remettre par écrit.</li><li>Conseiller de <strong>garder le plâtre sec</strong>, de ne pas le vernir, le couper ou en retirer le rembourrage.</li><li>Prévoir des consultations de suivi avec <strong>contrôle radiographique</strong> à <strong>J2, J8, J21, J45, J90</strong>, puis selon les cas.</li></ul>"},{"i":"3a5ac5c08760","n":365,"o":"365-3","u":"Prise en charge","t":"Savoir prévenir les complications à la mise en place d’une contention","q":"Dans quels cas une prophylaxie thromboembolique est-elle indiquée chez un patient sous plâtre ?","a":"<p>Une prophylaxie par <strong>HBPM quotidienne</strong> est indiquée dès que le patient est <strong>pubère</strong>pour :</p><ul><li>Tout plâtre du <strong>membre inférieur</strong> (que l'appui soit autorisé ou non).</li><li>Tout corset pour <strong>fracture du rachis</strong> (colonne vertébrale).</li></ul>"},{"i":"81c36edb81d8","n":365,"o":"365-3","u":"Prise en charge","t":"Savoir prévenir les complications à la mise en place d’une contention","q":"Comment lutter contre l'œdème sous plâtre, notamment durant les 48-72 premières heures ?","a":"<ul><li><strong>Surélévation du membre</strong> au-dessus du niveau du cœur (ex: écharpe poignet > coude au membre supérieur ; surélever les pieds du lit de 5 à 10 cm au membre inférieur).</li><li>Application de <strong>froid</strong> au contact du plâtre sur une grande longueur.</li><li>Réalisation de <strong>contractions isométriques</strong> sous plâtre et mobilisation des articulations laissées libres (doigts, orteils).</li></ul>"},{"i":"9cf319db4f5c","n":365,"o":"365-3","u":"Prise en charge","t":"Savoir prévenir les complications à la mise en place d’une contention","q":"Quelles sont les précautions à prendre lors de la confection d'un plâtre pour prévenir les complications ?","a":"<ul><li>Utiliser une <strong>gouttière d'emblée</strong> après tout traumatisme aigu (jamais de plâtre circulaire fermé d'emblée). En cas de plâtre circulaire, le <strong>fendre immédiatement</strong>.</li><li><strong>Rembourrer les reliefs osseux et les trajets vasculo-nerveux</strong>. Appliquer les bandes <strong>sans tension ni pli</strong>.</li><li>Laisser les <strong>doigts et orteils libres</strong> et respecter la position de fonction (ex: coude jamais > 90° en BABP).</li><li>Ne pas créer de « manche roulée » (effet garrot) à la racine du membre.</li><li>Pour une botte plâtrée, elle doit remonter <strong>au-dessus de la tête de la fibula</strong> pour ne pas comprimer le nerf fibulaire commun."},{"i":"eddd6dbc4803","n":365,"o":"365-3","u":"Prise en charge","t":"Savoir prévenir les complications à la mise en place d’une contention","q":"Quels sont les principes fondamentaux pour la prévention des complications lors de la mise en place d'une contention (plâtre) ?","a":"<p>Les trois leviers de prévention sont :</p><ul><li>Un <strong>plâtre bien fait</strong> techniquement.</li><li>La <strong>lutte contre l'œdème</strong>.</li><li>La <strong>prophylaxie thromboembolique</strong>.</li></ul>"},{"i":"1573d521cf04","n":365,"o":"365-5","u":"Suivi et/ou pronostic","t":"Connaître les conseils à donner au porteur d’un plâtre","q":"Quels sont les conseils à donner à un patient pour protéger son plâtre et gérer la tolérance cutanée ?","a":"<p>Pour protéger son plâtre et gérer la tolérance cutanée, le patient doit :</p><ul><li><strong>Garder le plâtre sec</strong> (même si c'est un plâtre en résine).</li><li>Ne pas vernir le plâtre pour éviter la macération.</li><li>Ne pas couper les bords ni retirer le rembourrage soi-même.</li><li>Ne pas gratter les démangeaisons sous le plâtre, ni glisser de poudre ou de déodorant.</li><li>Consulter en cas de peau rouge ou à vif.</li><li>Savoir que l'hypertrichose (pousse excessive de poils) régresse après l'ablation du plâtre.</li></ul>"},{"i":"2fb2fb73df9a","n":365,"o":"365-5","u":"Suivi et/ou pronostic","t":"Connaître les conseils à donner au porteur d’un plâtre","q":"Quelles sont les précautions à prendre concernant le retrait d'un plâtre et la prévention de la MTEV ?","a":"<p>Les précautions sont les suivantes :</p><ul><li>Le patient ne doit <strong>jamais retirer le plâtre lui-même</strong> car il y a un risque de couper la peau et surtout d'empêcher la consolidation de la fracture (une fracture nécessite des semaines à des mois pour se ressouder).</li><li>Concernant la prévention de la MTEV (Maladie Thrombo-Embolique Veineuse) : une prescription d'<strong>HBPM quotidienne</strong> est nécessaire pour les patients <strong>dès la puberté</strong> en cas de plâtre du membre inférieur et pour tout corset rachidien.</li></ul>"},{"i":"31537601d90f","n":365,"o":"365-5","u":"Suivi et/ou pronostic","t":"Connaître les conseils à donner au porteur d’un plâtre","q":"Quels signes d'alarme doivent faire consulter en urgence un patient porteur d'un plâtre ?","a":"<p>Un patient porteur d'un plâtre doit consulter en urgence en cas de :</p><ul><li><strong>Douleur</strong> augmentant progressivement, non soulagée par les antalgiques, sensation de brûlure ou de pression.</li><li><strong>Signes neurologiques</strong> : engourdissement, picotements, perte de mobilité active des doigts/orteils.</li><li><strong>Signes vasculaires</strong> : doigts/orteils décolorés (blancs), froids voire glacés.</li><li><strong>Signes de MTEV</strong> (Maladie Thrombo-Embolique Veineuse) : fièvre, douleurs respiratoires, hémoptysie.</li><li><strong>Signes d'infection</strong> : taches sur le plâtre et odeur nauséabonde.</li><li>En cas de corset : intolérance gastrique, nausées, vomissements.</li></ul>"},{"i":"52eaee759ed8","n":365,"o":"365-5","u":"Suivi et/ou pronostic","t":"Connaître les conseils à donner au porteur d’un plâtre","q":"Quels sont les conseils pratiques pour limiter l'œdème sous plâtre ?","a":"<p>Pour limiter l'œdème sous plâtre, notamment durant les <strong>48 à 72 premières heures</strong>, il faut :</p><ul><li>Ne pas porter de vêtement roulé en garrot.</li><li>Appliquer du froid au contact du plâtre.</li><li>Surélever le membre plâtré au-dessus du niveau du cœur.</li><li>Réaliser des exercices isométriques et mobiliser les articulations laissées libres.</li></ul>"},{"i":"c905cfca9fb0","n":365,"o":"365-5","u":"Suivi et/ou pronostic","t":"Connaître les conseils à donner au porteur d’un plâtre","q":"Quelles sont les recommandations concernant la marche, la conduite et la gestion d'un corset ?","a":"<p>Les recommandations sont les suivantes :</p><ul><li>Pour la <strong>marche ou l'appui</strong> : attendre le séchage complet du plâtre, soit environ <strong>1 heure pour la résine</strong> et <strong>36 à 48 heures pour le plâtre</strong>.</li><li>Pour la <strong>conduite</strong> : elle est <strong>interdite</strong> avec toute immobilisation plâtrée.</li><li>En cas de <strong>corset</strong> : fractionner l'alimentation en <strong>5 repas par jour</strong>, supprimer les boissons gazeuses et les chewing-gums pour éviter la dilatation gastrique.</li></ul>"},{"i":"5e89aa3632aa","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Quels sont les signes d'une compression nerveuse sous plâtre ?","a":"<p>Une compression nerveuse sous plâtre se manifeste par un <strong>déficit sensitivomoteur</strong> dans le territoire du nerf atteint. Les localisations classiques sont :</p><ul><li>Nerf fibulaire commun (col de la fibula)</li><li>Nerf ulnaire (gouttière épitrochléo-olécrânienne)</li><li>Nerf médian (pli du coude, poignet)</li><li>Nerf radial (diaphyse humérale, 10 cm au-dessus du coude)</li></ul>"},{"i":"61429fad3eeb","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Comment dépister une complication cutanée ou infectieuse chez un patient porteur d'un plâtre ?","a":"<p>Les signes d'appel d'une complication cutanée ou infectieuse (escarre, arthrite, ostéite) sont :</p><ul><li>Douleur localisée</li><li>Fébricule</li><li>Adénopathies</li><li>Odeur inhabituelle provenant du plâtre</li><li>Taches sur le plâtre (témoignant d'un écoulement)</li><li>Fièvre</li></ul>"},{"i":"7d75b98c0efe","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Quels sont les signes devant faire suspecter une complication thromboembolique (TVP/EP) chez un patient sous plâtre ?","a":"<p>Les signes à rechercher sont :</p><ul><li>Pour une <strong>Thrombose Veineuse Profonde (TVP)</strong> :<ul><li>Douleur du mollet</li><li>Œdème du dos du pied</li><li>Cyanose</li><li>Dissociation pouls-température</li></ul></li><li>Pour une <strong>Embolie Pulmonaire (EP)</strong> :<ul><li>Dyspnée</li><li>Hémoptysie</li></ul></li></ul>"},{"i":"8851f044dda8","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Dans le cadre de la surveillance d'un plâtre, quelle est la formulation correcte à utiliser pour demander une radiographie de contrôle ?","a":"<p>Pour demander une radiographie de contrôle, il est impératif d'écrire « <strong>radiographie AVEC plâtre</strong> » pour éviter toute confusion avec une demande de retrait du plâtre avant l'examen.</p>"},{"i":"a63865691487","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Quels points clés de la surveillance clinique permettent de dépister une complication sous plâtre ?","a":"<p>Les points clés de la surveillance clinique d'un patient sous plâtre sont la recherche systématique de :</p><ul><li><strong>Douleur</strong></li><li><strong>Œdème</strong></li><li><strong>Paresthésies</strong></li><li><strong>Cyanose</strong></li><li><strong>Douleur à la mobilisation passive des extrémités</strong> (doigts/orteils)</li></ul>"},{"i":"cef0aaf566a7","n":365,"o":"365-6","u":"Identifier une urgence","t":"Savoir dépister et diagnostiquer une complication sous plâtre","q":"Quelles sont les complications locales ou locorégionales à rechercher en priorité chez un patient porteur d’un plâtre, et leurs signes d'appel ?","a":"<p>Il faut rechercher principalement :</p><ul><li>Le <strong>syndrome compartimental</strong>, qui est une urgence : <ul><li>Douleur disproportionnée, résistante à la morphine</li><li>Majorée à la mobilisation passive</li><li>Cyanose distale</li></ul></li><li>L'<strong>ischémie vasculaire</strong>, qui est aussi une urgence :<ul><li>Extrémités froides, pâles</li><li>Abolition des pouls</li></ul></li></ul>"},{"i":"5ff2a6d470e3","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Quelle est la prise en charge spécifique à mettre en œuvre en urgence devant un syndrome des loges sous plâtre ?","a":"<p>Devant un syndrome des loges sous plâtre, la prise en charge consiste en une <strong>ablation du plâtre</strong> associée à une <strong>aponévrotomie (fasciotomie) en urgence</strong> (dans les <strong>< 6 heures</strong>) de toutes les loges concernées.</p>"},{"i":"843eacd80b3e","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Quelle est la conduite à tenir face à une suspicion de thrombose veineuse profonde (TVP) ou d'embolie pulmonaire (EP) chez un patient sous plâtre ?","a":"<p>Face à une suspicion de TVP ou d'EP, le plâtre doit être <strong>coupé en bivalve voire enlevé</strong>. Il faut réaliser un <strong>écho-doppler veineux</strong> et initier une <strong>anticoagulation curative immédiate</strong>.</p>"},{"i":"9d68c35ca33b","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Quel est le premier geste réflexe à réaliser en cas de suspicion d'urgence loco-régionale, vasculaire, nerveuse ou thromboembolique sous plâtre ?","a":"<p>Le premier geste réflexe est de <strong>fendre le plâtre (bivalve)</strong>, voire de l'enlever. Il faut ensuite surélever le membre et réévaluer rapidement la sensibilité, la motricité, la coloration et le pouls.</p>"},{"i":"c9424590cc00","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Comment corrige-t-on un déplacement secondaire sous plâtre, notamment avant la 3ème semaine ?","a":"<p>Un déplacement secondaire sous plâtre peut être corrigé par <strong>gypsotomie</strong> (correction sans anesthésie) ou, si nécessaire, par <strong>réduction sous anesthésie générale (AG)</strong>, potentiellement suivie d'une ostéosynthèse. Cette complication doit être dépistée avant la 3ème semaine.</p>"},{"i":"e712f3315fcd","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Comment prend-on en charge une ischémie de membre survenant sous plâtre ?","a":"<p>En cas d'ischémie de membre sous plâtre, il faut procéder à l'<strong>ablation immédiate de la contention</strong> et solliciter un <strong>avis chirurgical vasculaire en urgence</strong> en vue d'une potentielle revascularisation.</p>"},{"i":"f4e1f6e567c2","n":365,"o":"365-7","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge en urgence d’une complication sous plâtre","q":"Quel est le principe fondamental en cas de suspicion de complication sous plâtre ?","a":"<p>Devant toute suspicion de complication sous plâtre, le principe commun est de <strong>lever la contrainte sans délai</strong>, puis de traiter la cause. Toute procrastination est interdite.</p>"}]};